```java
import java.util.*;

// src PRODUCES values -> extends; dst CONSUMES values -> super
static <T> void copy(List<? extends T> src, List<? super T> dst) {
    for (T item : src) {   // read from producer as T
        dst.add(item);     // write into consumer
    }
}

List<Integer> src = List.of(1, 2, 3);
List<Number> dst = new ArrayList<>();
copy(src, dst);            // flexible: Integer -> Number
```
Use `extends` for the source you read, `super` for the destination you write.

```java
import java.util.*;

// Generic class
class Box<T> {
    private T value;
    public void set(T value) { this.value = value; }
    public T get() { return value; }
}

class Utils {
    // Generic method - <T> before the return type
    static <T> T first(List<T> list) { return list.get(0); }

    // Bounded generic method - T must be Comparable
    static <T extends Comparable<T>> T max(List<T> list) {
        T best = list.get(0);
        for (T t : list) if (t.compareTo(best) > 0) best = t;
        return best;
    }
}

// Usage - T is inferred from the arguments:
Box<String> b = new Box<>(); b.set("hi");
String f = Utils.first(List.of("a", "b"));   // T = String
int m = Utils.max(List.of(3, 1, 2));         // T = Integer -> 3
```
